// Draw stack of vinyl records
const records = 5;
const baseY = 300;
const recordRadius = 100;

// Draw base circle for records
ctx.fillStyle = BLACK;
ctx.beginPath();
ctx.arc(W/2, baseY, 120, 0, Math.PI * 2);
ctx.fill();

// Draw each record
for (let i = 0; i < records; i++) {
    const y = baseY - i * 20;

    // Record outer edge
    ctx.fillStyle = SILVER;
    ctx.beginPath();
    ctx.arc(W/2, y, recordRadius, 0, Math.PI * 2);
    ctx.fill();

    // Record center
    ctx.fillStyle = BLACK;
    ctx.beginPath();
    ctx.arc(W/2, y, recordRadius * 0.6, 0, Math.PI * 2);
    ctx.fill();

    // Record grooves (simple lines)
    ctx.strokeStyle = '#444444';
    ctx.lineWidth = 1;
    for (let j = 0; j < 12; j++) {
        const angle = (j / 12) * Math.PI * 2;
        const x1 = W/2 + Math.cos(angle) * recordRadius;
        const y1 = y + Math.sin(angle) * recordRadius;
        const x2 = W/2 + Math.cos(angle) * (recordRadius * 0.9);
        const y2 = y + Math.sin(angle) * (recordRadius * 0.9);
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
    }

    // Record label details
    ctx.fillStyle = GOLD;
    ctx.beginPath();
    ctx.arc(W/2, y, recordRadius * 0.4, 0, Math.PI * 2);
    ctx.fill();

    // Add some texture
    ctx.fillStyle = RED;
    for (let j = 0; j < 5; j++) {
        const angle = (j / 5) * Math.PI * 2;
        const x = W/2 + Math.cos(angle) * (recordRadius * 0.3);
        const y = y + Math.sin(angle) * (recordRadius * 0.3);
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fill();
    }
}

