// Draw spiral in cool tones
function drawSpiral(x, y, size, angle, depth) {
    if (depth > 0) {
        // Calculate new position
        const newX = x + Math.cos(angle) * size;
        const newY = y + Math.sin(angle) * size;

        // Draw line segment
        ctx.strokeStyle = `hsl(${200 - depth * 10}, 70%, ${60 - depth * 5}%)`;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(newX, newY);
        ctx.stroke();

        // Recursive call for next iteration
        drawSpiral(newX, newY, size * 0.8, angle + 0.3, depth - 1);
    }
}

