// Shell spiral (green)
ctx.fillStyle = '#228B22';
ctx.beginPath();
let radius = 0;
const centerX = 200;
const centerY = 250;
const steps = 30;
const angleStep = Math.PI / 6;

for (let i = 0; i < steps; i++) {
    const angle = i * angleStep;
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);

    if (i === 0) {
        ctx.moveTo(x, y);
    } else {
        ctx.lineTo(x, y);
    }

    radius += 8;
}

ctx.closePath();
ctx.fill();

// Shell details (white)
ctx.fillStyle = '#FFFFFF';
for (let i = 0; i < steps; i++) {
    const angle = i * angleStep;
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);

    if (i > 0) {
        ctx.beginPath();
        ctx.arc(x, y, 2, 0, Math.PI * 2);
        ctx.fill();
    }

    radius += 8;
}

// Shell pattern (blue)
ctx.fillStyle = '#1E90FF';
for (let i = 0; i < steps; i++) {
    const angle = i * angleStep;
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);

    if (i > 0 && i % 3 === 0) {
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
    }

    radius += 8;
}

// Shell spiral lines (gray)
ctx.strokeStyle = '#696969';
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(centerX, centerY);
for (let i = 0; i < steps; i++) {
    const angle = i * angleStep;
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);
    ctx.lineTo(x, y);
}
ctx.stroke();

// Shell spiral center (red)
ctx.fillStyle = '#FF0000';
ctx.beginPath();
ctx.arc(centerX, centerY, 10, 0, Math.PI * 2);
ctx.fill();

